export function latLonToTokyoWorld(
  lat: number,
  lon: number
): [number, number] {
  const rawKmX = (lon - TOKYO_GEO_CONFIG.centerLon) * (TOKYO_GEO_CONFIG.kmPerDegLon ?? 90);
  const rawKmZ = -(lat - TOKYO_GEO_CONFIG.centerLat) * (TOKYO_GEO_CONFIG.kmPerDegLat ?? 111.1);
  const distKm = Math.hypot(rawKmX, rawKmZ);
  const coreRadiusKm = TOKYO_GEO_CONFIG.coreRadiusKm ?? 7.5;
  const worldUnitsPerKm = TOKYO_GEO_CONFIG.worldUnitsPerKm ?? 10.8;
  let effectiveKm = distKm;
  if (distKm > coreRadiusKm) {
    effectiveKm = coreRadiusKm + Math.log1p((distKm - coreRadiusKm) * 0.30) * 5.6;
  }
  const scale = distKm > 0.0001 ? (effectiveKm / distKm) * worldUnitsPerKm : worldUnitsPerKm;
  return [Math.round(rawKmX * scale * 100) / 100, Math.round(rawKmZ * scale * 100) / 100];
}

